const $=id=>document.getElementById(id);let api=['localhost','127.0.0.1','akis-indir-api.onrender.com'].includes(location.hostname)?'':'https://akis-indir-api.onrender.com', info,mode,quality,busy=false;const local=['localhost','127.0.0.1'].includes(location.hostname);const status=t=>$('status').textContent=t;
async function call(path,data){const r=await fetch(api+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(180000)});const j=await r.json();if(!r.ok)throw Error(j.error||'İşlem tamamlanamadı.');return j}
function lock(value){busy=value;['audio','video','download'].forEach(id=>$(id).disabled=value);$('url').disabled=value;document.querySelectorAll('.choices button').forEach(b=>b.disabled=value)}
async function analyze(type){if(busy)return;let url=$('url').value.trim();try{if(!['http:','https:'].includes(new URL(url).protocol))throw Error()}catch{status('Önce geçerli bir video bağlantısı yapıştır.');$('url').focus();return}mode=type;lock(true);$('result').hidden=true;status('Bağlantı inceleniyor… İlk kullanımda sunucunun açılması yaklaşık bir dakika sürebilir.');try{info=await call('/api/info',{url});$('title').textContent=info.title;$('meta').textContent=[info.uploader,info.duration?Math.floor(info.duration/60)+' dk':'',type==='audio'?'Ses kalitesi':'Video kalitesi'].filter(Boolean).join(' · ');const opts=type==='audio'?info.audio:info.video;if(!opts.length)throw Error('Bu içerikte seçilen tür bulunamadı.');quality=opts[0].value;$('choices').replaceChildren();opts.forEach((o,i)=>{const b=document.createElement('button');b.textContent=o.label;b.className=i?'':'selected';b.setAttribute('aria-pressed',!i);b.onclick=()=>{quality=o.value;for(const c of $('choices').children){c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',c===b)}};$('choices').append(b)});$('result').hidden=false;$('progress').hidden=true;status('Hazır. Kaliteyi seçip indirebilirsin.')}catch(e){status('Bağlantı çözümlenemedi. '+(e.message==='Failed to fetch'?'İndirme sunucusuna ulaşılamıyor.':e.message))}finally{lock(false)}}
$('audio').onclick=()=>analyze('audio');$('video').onclick=()=>analyze('video');$('url').oninput=()=>{$('result').hidden=true;info=null;status('')};$('url').onkeydown=e=>{if(e.key==='Enter')analyze('video')};
$('download').onclick=async()=>{if(busy||!info)return;lock(true);$('progress').hidden=false;$('progress').removeAttribute('value');status('İndirme hazırlanıyor…');try{const job=await call('/api/download',{url:info.url,mode,quality});let done=false;const deadline=Date.now()+12*60*1000;while(!done){if(Date.now()>deadline)throw Error('İşlem zaman aşımına uğradı. Yeniden dene.');await new Promise(r=>setTimeout(r,1200));const j=await call('/api/jobs/'+job.id);if(j.state==='error')throw Error(j.error);if(j.progress!=null)$('progress').value=j.progress;status(j.state==='processing'?'Dosya dönüştürülüyor…':`İndiriliyor… %${Math.round(j.progress||0)}`);if(j.state==='done'){done=true;const a=document.createElement('a');a.href=api+'/api/file/'+job.id;a.download='';a.click();status('Dosya hazır. İndirme başlamadıysa: ');a.textContent='Dosyayı indir ↓';a.style.color='var(--green)';$('status').append(a);$('progress').value=100}}}catch(e){status('İndirme tamamlanamadı. '+e.message)}finally{lock(false)}};
